const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1) Geometry & Time
    const regions = [
      { name: 'EastMidlands_Part', geom: ee.Geometry.Polygon([[[-1.8,52.8],[0.2,52.8],[0.2,53.5],[-1.8,53.5],[-1.8,52.8]]]) },
      { name: 'NE_England_Part', geom: ee.Geometry.Polygon([[[-2.2,54.7],[-0.8,54.7],[-0.8,55.8],[-2.2,55.8],[-2.2,54.7]]]) },
      { name: 'E_Scotland_Part', geom: ee.Geometry.Polygon([[[-3.2,56.0],[-1.5,56.0],[-1.5,57.4],[-3.2,57.4],[-3.2,56.0]]]) }
    ];
    const obsStart = ee.Date('2023-10-01');
    const obsEnd = ee.Date('2024-01-05'); // end exclusive
    const scale = 3000;

    // 2) Data acquisition and checks
    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').select('precipitation');
    const obsCol = chirps.filterDate(obsStart, obsEnd);
    const obsSize = await evaluate(obsCol.size());
    if (!isFiniteNumber(obsSize)) { console.log('Obs images: NaN'); console.log('C3'); return; }
    if (obsSize === 0) { console.log('Obs images: 0'); console.log('C1'); return; }
    console.log(`Obs images: ${obsSize}`);

    const years = ee.List.sequence(1991, 2020);
    const yearlySums = ee.ImageCollection(years.map(function(y) {
      y = ee.Number(y);
      const s = ee.Date.fromYMD(y, 10, 1);
      const e = ee.Date.fromYMD(y.add(1), 1, 5);
      const c = chirps.filterDate(s, e);
      return c.sum().rename('precipitation').set({year: y, count: c.size()});
    }));
    const yearCounts = await evaluate(yearlySums.aggregate_array('count'));
    const yearsWithData = Array.isArray(yearCounts) ? yearCounts.filter(n => n > 0).length : 0;
    if (!isFiniteNumber(yearsWithData)) { console.log('Baseline years with data: NaN/30'); console.log('C3'); return; }
    if (yearsWithData === 0) { console.log('Baseline years with data: 0/30'); console.log('C1'); return; }
    console.log(`Baseline years with data: ${yearsWithData}/30`);

    // 3) Processing
    const obsSum = obsCol.sum().rename('obs');
    const climMean = yearlySums.mean().rename('clim');
    const combo = ee.Image.cat([obsSum, climMean]);

    // 4) Region stats
    let anyInvalid = false;
    let anyZeroPixels = false;
    let allGreater = true;

    for (const r of regions) {
      const stats = await evaluate(combo.reduceRegion({
        reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: r.geom, scale: scale, maxPixels: 1e9, bestEffort: true
      }));
      const obsMean = stats ? stats['obs_mean'] : null;
      const climMeanVal = stats ? stats['clim_mean'] : null;
      const pixCount = stats ? stats['obs_count'] : null;

      if (!isFiniteNumber(pixCount) || pixCount === 0) { anyZeroPixels = true; }

      if (!isFiniteNumber(obsMean) || !isFiniteNumber(climMeanVal)) { anyInvalid = true; }

      const diff = (isFiniteNumber(obsMean) && isFiniteNumber(climMeanVal)) ? (obsMean - climMeanVal) : null;
      if (!(isFiniteNumber(obsMean) && isFiniteNumber(climMeanVal) && obsMean > climMeanVal)) { allGreater = false; }

      console.log(`${r.name}: Obs(mm)=${fmt(obsMean)} Climo(mm)=${fmt(climMeanVal)} Diff=${fmt(diff)} Pixels=${fmt(pixCount,0)}`);
    }

    // 5) Validation & Final Answer
    if (anyInvalid) { console.log('C3'); return; }
    if (anyZeroPixels) { console.log('C2'); return; }
    console.log(allGreater ? 'A' : 'B');

  } catch (err) {
    console.log('D');
  }
}

function fmt(v, decimals=1) {
  if (!isFiniteNumber(v)) return 'NaN';
  const f = Math.pow(10, decimals);
  return String(Math.round(v * f) / f);
}
function isFiniteNumber(x) { return typeof x === 'number' && isFinite(x); }
function evaluate(eeObj) {
  return new Promise((resolve, reject) => {
    eeObj.evaluate((res, err) => err ? reject(err) : resolve(res));
  });
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
